std::size_t numThreads = std::thread::hardware_concurrency();
std::size_t chunkSize = (end - start) / numThreads;
std::vector<std::thread> threads;

for (std::size_t i = 0; i < numThreads; ++i) {
    std::size_t chunkStart = start + i * chunkSize;
    std::size_t chunkEnd = (i == numThreads - 1) ? end : chunkStart + chunkSize;
    threads.emplace_back([&, chunkStart, chunkEnd]() {
        for (std::size_t j = chunkStart; j < chunkEnd; ++j) {
            float x = particles[j].x;
            float y = particles[j].y;
            float z = particles[j].z;
            int hashX = std::floor(x / h);
            int hashY = std::floor(y / h);
            int hashZ = std::floor(z / h);
            particles[j].hash = hashX + hashY * 1000 + hashZ * 1000000;
        }
    });
}

for (auto& thread : threads) {
    thread.join();
}

